import{_ as i,C as r,c as l,o as c,a3 as o,G as n,j as s,a}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Invoicing processes","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/customer-invoices/index.md","filePath":"master/finance/customer-invoices/index.md","lastUpdated":1791902625000}'),d={name:"master/finance/customer-invoices/index.md"};function h(u,e,g,m,p,f){const t=r("ImagePopup");return c(),l("div",null,[e[0]||(e[0]=o('<h1 id="invoicing-processes" tabindex="-1">Invoicing processes <a class="header-anchor" href="#invoicing-processes" aria-label="Permalink to &quot;Invoicing processes&quot;">​</a></h1><p>An invoice asks a customer to pay for what you sold. In Aureus an invoice can start in three ways: from a sales order, by hand, or as a credit note from an existing invoice. This page shows each way, then follows an invoice from its first draft to the day it is paid.</p><blockquote><p><strong>In simple words:</strong> Pick the way that matches your sale, check the draft, confirm it, send it and record the payment.</p></blockquote><p>You can do all of this in the <strong>Invoices</strong> app or in the <strong>Accounting</strong> app. The screens are identical. Each page names both menu paths, for example <code>Invoices → Customers → Invoices</code> or <code>Accounting → Customers → Invoices</code>.</p><h2 id="process-1-invoice-from-a-sales-order" tabindex="-1">Process 1: invoice from a sales order <a class="header-anchor" href="#process-1-invoice-from-a-sales-order" aria-label="Permalink to &quot;Process 1: invoice from a sales order&quot;">​</a></h2><p>Use this process when the sale started in the <strong>Sales</strong> app. You do not retype anything. Aureus copies the customer and the lines from the order.</p><ol><li>Open the confirmed sales order.</li><li>Click <strong>Create Invoice</strong>.</li></ol>',7)),n(t,{src:"/images1/finance/so_create_invoice_button.png",alt:"Confirmed sales order SO/3 with the Create Invoice button in the page header"}),e[1]||(e[1]=s("ol",{start:"3"},[s("li",null,[a("Choose "),s("strong",null,"Regular invoice"),a(". This is the only type Aureus offers.")]),s("li",null,[a("Click "),s("strong",null,"Submit"),a(".")])],-1)),n(t,{src:"/images1/finance/so_create_invoice_modal.png",alt:"Create Invoice window with Regular invoice selected and the Submit button"}),e[2]||(e[2]=o('<ol start="5"><li>Aureus creates a <strong>Draft</strong> invoice and links it to the order. The order number shows in <strong>Source Document</strong>.</li><li>Open the invoice, check the lines and click <strong>Confirm</strong>.</li></ol><p>See <a href="./../../sales/sales/quotations-orders/manage-orders.html">Manage orders</a> for the order itself and <a href="./../../sales/sales/invoicing/order-to-invoice.html">Order to invoice</a> for the full flow.</p><h2 id="process-2-invoice-by-hand" tabindex="-1">Process 2: invoice by hand <a class="header-anchor" href="#process-2-invoice-by-hand" aria-label="Permalink to &quot;Process 2: invoice by hand&quot;">​</a></h2><p>Use this process for a sale that has no order, such as a service you bill directly.</p><ol><li>Go to <code>Invoices → Customers → Invoices</code> or <code>Accounting → Customers → Invoices</code>.</li><li>Click <strong>New Invoice</strong>.</li><li>Pick the <strong>Customer</strong>, add the <strong>Invoice Lines</strong> and click <strong>Create</strong>.</li><li>Click <strong>Confirm</strong>.</li></ol>',5)),n(t,{src:"/images1/finance/invoice_list.png",alt:"Invoices list where you click New Invoice"}),e[3]||(e[3]=o('<p>The customer must already exist. To add one, see <a href="./../../getting-started/contacts/contacts.html">Contacts</a> and <a href="./../../sales/sales/quotations-orders/manage-customers.html">Manage customers</a>. The full form is in <a href="./create-invoice.html">Create an invoice</a>.</p><h2 id="process-3-credit-note-from-an-invoice" tabindex="-1">Process 3: credit note from an invoice <a class="header-anchor" href="#process-3-credit-note-from-an-invoice" aria-label="Permalink to &quot;Process 3: credit note from an invoice&quot;">​</a></h2><p>Use this process when a posted invoice is wrong, or when goods come back.</p><ol><li>Open the posted invoice.</li><li>Click <strong>Credit Note</strong>.</li><li>Fill in <strong>Reason</strong>, <strong>Journal</strong> and <strong>Date</strong>, then submit.</li><li>Aureus creates a <strong>Draft</strong> credit note with the same lines. Edit it if the credit is partial.</li><li>Click <strong>Confirm</strong>.</li></ol>',4)),n(t,{src:"/images1/finance/credit_note_button_modal.png",alt:"Create Credit Note window on a posted invoice with Reason, Journal and Date filled in"}),e[4]||(e[4]=o('<p>See <a href="./credit-notes-and-refunds.html">Credit notes and refunds</a>.</p><h2 id="the-life-of-an-invoice" tabindex="-1">The life of an invoice <a class="header-anchor" href="#the-life-of-an-invoice" aria-label="Permalink to &quot;The life of an invoice&quot;">​</a></h2><p>The <strong>State</strong> tells you where the invoice is in its life.</p><ul><li><strong>Draft:</strong> You are still working. You can change everything. Nothing is recorded in your accounts.</li><li><strong>Posted:</strong> You confirmed it. It is a real accounting document and most fields are locked.</li><li><strong>Cancelled:</strong> You cancelled a draft. It stays in the list for your records.</li></ul><h3 id="buttons-in-each-state" tabindex="-1">Buttons in each state <a class="header-anchor" href="#buttons-in-each-state" aria-label="Permalink to &quot;Buttons in each state&quot;">​</a></h3>',5)),n(t,{src:"/images1/finance/invoice_view_posted.png",alt:"Posted invoice with its header buttons, state bar, payment state and totals"}),e[5]||(e[5]=o('<table tabindex="0"><thead><tr><th>State</th><th>Buttons</th></tr></thead><tbody><tr><td>Draft</td><td><strong>Confirm</strong>, <strong>Cancel</strong>, <strong>Delete</strong></td></tr><tr><td>Posted</td><td><strong>Print &amp; Send</strong>, <strong>Preview</strong>, <strong>Pay</strong>, <strong>Set as Checked</strong>, <strong>Credit Note</strong>, <strong>Reset To Draft</strong></td></tr><tr><td>Cancelled</td><td><strong>Reset To Draft</strong></td></tr></tbody></table><h3 id="what-posting-does" tabindex="-1">What posting does <a class="header-anchor" href="#what-posting-does" aria-label="Permalink to &quot;What posting does&quot;">​</a></h3><p>When you click <strong>Confirm</strong>, Aureus checks the invoice, fills the invoice date if it is empty, and creates the journal entry. The customer balance goes up. Your income and tax accounts are credited. The invoice number does not change. See <a href="./invoice-sequence.html">Invoice sequence</a> and <a href="./../accounting-entries/journal-entries.html">Journal entries</a>.</p><h3 id="payment-state" tabindex="-1">Payment state <a class="header-anchor" href="#payment-state" aria-label="Permalink to &quot;Payment state&quot;">​</a></h3><p>A posted invoice also has a <strong>Payment State</strong>.</p><ul><li><strong>Not paid:</strong> Nothing is paid yet.</li><li><strong>Partial:</strong> The customer paid part of the total. <strong>Amount Due</strong> shows what is left.</li><li><strong>In payment:</strong> A payment is recorded but not yet fully processed.</li><li><strong>Paid:</strong> The <strong>Amount Due</strong> is zero.</li><li><strong>Reversed:</strong> The invoice was reversed, for example by a credit note.</li></ul><h3 id="how-a-payment-settles-the-invoice" tabindex="-1">How a payment settles the invoice <a class="header-anchor" href="#how-a-payment-settles-the-invoice" aria-label="Permalink to &quot;How a payment settles the invoice&quot;">​</a></h3><ol><li>Click <strong>Pay</strong> on the posted invoice.</li><li>Enter the amount, date and journal, then confirm.</li><li>Aureus matches the payment with the invoice. The <strong>Amount Due</strong> falls and the <strong>Payment State</strong> changes.</li><li>The <strong>Payments</strong> tab lists the payment.</li></ol>',8)),n(t,{src:"/images1/finance/pay_window_invoice.png",alt:"Pay window with Journal, Payment Method, Amount, Currency and Payment Date filled in"}),e[6]||(e[6]=o('<p>See <a href="./../payments/register-payment.html">Register a payment</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <strong>Draft</strong> view in the invoice list every morning. It shows the invoices that still wait for you to confirm them.</p></div><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./create-invoice.html">Create an invoice</a>: the full invoice form, buttons and tabs.</li><li><a href="./credit-notes-and-refunds.html">Credit notes and refunds</a>: reduce or cancel a posted invoice or bill.</li><li><a href="./payment-terms.html">Payment terms</a>: rules such as &quot;pay within 30 days&quot;.</li><li><a href="./incoterms.html">Incoterms</a>: delivery terms you can print on an invoice.</li><li><a href="./invoice-sequence.html">Invoice sequence</a>: how document numbers are built.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../vendor-bills/">Vendor bills</a></li><li><a href="./../payments/">Payments</a></li><li><a href="./../taxes/">Taxes</a></li></ul>',6))])}const y=i(d,[["render",h]]);export{_ as __pageData,y as default};
